# Safe File Operations 🔒

Always handle potential file errors!

## Safe File Reading

```file
def read_file_safely(filename):
    try:
        with open(filename, "r", encoding="utf-8") as file:
            return file.read()
    except FileNotFoundError:
        print(f"Error: '{filename}' not found")
        return None
    except PermissionError:
        print(f"Error: No permission to read '{filename}'")
        return None
    except UnicodeDecodeError:
        print(f"Error: Cannot decode '{filename}'")
        return None

content = read_file_safely("data.txt")
if content:
    print(content)
```

## Safe JSON Loading

```file
import json

def load_json_safely(filename):
    try:
        with open(filename, "r") as file:
            return json.load(file)
    except FileNotFoundError:
        print(f"File not found: {filename}")
        return None
    except json.JSONDecodeError as e:
        print(f"Invalid JSON: {e}")
        return None

data = load_json_safely("config.json")
```

## Raising Exceptions

```file
def validate_age(age):
    if not isinstance(age, int):
        raise TypeError("Age must be an integer!")
    if age < 0:
        raise ValueError("Age cannot be negative!")
    return age

try:
    validate_age(-5)
except ValueError as e:
    print(e)  # "Age cannot be negative!"
```

# Custom Exceptions 🎨

Create your own exception types for specific error scenarios.

## Basic Custom Exception

```file
class InvalidAgeError(Exception):
    """Raised when age is invalid"""
    pass

def set_age(age):
    if age < 0 or age > 150:
        raise InvalidAgeError(f"Invalid age: {age}")
    return age

try:
    set_age(200)
except InvalidAgeError as e:
    print(e)  # "Invalid age: 200"
```

## Custom Exception with Attributes

```file
class ValidationError(Exception):
    def __init__(self, field, message):
        self.field = field
        self.message = message
        super().__init__(f"{field}: {message}")

def validate_email(email):
    if "@" not in email:
        raise ValidationError("email", "Must contain @")

try:
    validate_email("invalid-email")
except ValidationError as e:
    print(f"Field: {e.field}")
    print(f"Error: {e.message}")
```

## Exception Hierarchy for Your App

```file
class AppError(Exception):
    """Base exception for our app"""
    pass

class DatabaseError(AppError):
    pass

class NetworkError(AppError):
    pass

class AuthenticationError(AppError):
    pass

# Now you can catch all app errors:
try:
    do_something()
except AppError as e:
    log_error(e)
```
